  intros ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m P IN E n p0 lo shi c pad7 pad2;
  intros PC PCOK IT ST PURE NR P0 PN MI AC SK AP;
  destruct PURE as ((LO & CEIL & APP & PAL & APE & EAL & DPE & SPAL & SHI) & ILO & IHI & IAL);
  pose proof (stack0_bounds _ _ _ SK) as [SKB1 SKB2];
  pose proof (aapp_bounds _ 80 APP ltac:(lia)) as (PB1 & PB2 & PB3 & PB4 & PB5);
  pose proof (aapp_bounds _ 24 APE ltac:(lia)) as (EB1 & EB2 & EB3 & EB4 & EB5);
  pose proof aceil_facts as (AF1 & AF2 & AF3);
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  pose proof (munch_refl [(lo, bv_unsigned sp)]%Z m) as MU; pose proof (wmono_refl asegs m) as WM;
  assert (FW : Forall awin [(lo, bv_unsigned sp)]%Z) by (apply Forall_cons; [apply awin_stack; exact CEIL| apply Forall_nil]);
