  unfold seg1_post, wrap_saved, shw; unfold ParserCoreCells in PC; unfold wz in *;
  cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f] in PC;
  carve_frame 112%nat ST;
  (* [comment removed for export] *)
  step; st1; st1; st1; st1; st1; st1; st1; st1; st1; st1; st1; step; step; step; step; clear G1 G2; step;
  (* [comment removed for export] *)
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    let RD := fresh "RD" in
    pose proof (stack0_read0_sr mc lo shi IN 8 (stack0_transport _ _ _ _ _ SK MU WM
                   ltac:(eapply Forall_impl; [| exact FW]; intros ?iv ?HW; exact (proj1 (proj2 HW))))
                  ltac:(clear - LO ILO; lia) ltac:(clear; lia) ltac:(clear - IHI; lia)) as RD;
    shchk_fast RD
  end;
  (* [comment removed for export] *)
  step; step;
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    let RD := fresh "RD" in
    pose proof (accessible_read0_in mc P 80 (P + 64) (acc_transport_awin _ _ mc P 80 AP MU FW) PAL eq_refl ltac:(clear; lia)) as RD;
    zstep; zstep; step; clear RD; sh0_lit; step; shchk_br
  end;
  (* [comment removed for export] *)
  step; change (zx32 (Z_to_bv 64 (pc_hlim c))) with (zx32 (wz (pc_hlim c))); rewrite zx32_of_wz by lia; unfold wz;
  step; step;
  let K := fresh "K" in
  if_cases K; zify_cond K; rewrite ?unsigned_lit in K by lia;
  [ (* [comment removed for export] *) replace (Z.min n (pc_hlim c)) with n by lia
  | (* [comment removed for export] *) step; replace (Z.min n (pc_hlim c)) with (pc_hlim c) by lia ];
  (* [comment removed for export] *)
  zstep;
  (repeat (lazymatch goal with
           | |- evt _ _ (MS _ _ (Z_to_bv 64 0xcf6fc) _ _ _ _) => fail
           | |- evt _ _ (MS _ _ (Z_to_bv 64 0xd0474) _ _ _ _) => fail
           | _ => step end));
  lazymatch goal with FR : rw_cells _ ?mc (bv_unsigned sp + -112) (CB 24 ?j24 :: ?rest) |- _ =>
    let FRlo := fresh "FRlo" in let FRhi := fresh "FRhi" in let ACf := fresh "ACf" in let SKf := fresh "SKf" in
    split_frameA FR [CB 24 j24] rest FRlo FRhi;
    pose proof (aconst_transport_awin _ _ mc AC MU WM FW) as ACf;
    pose proof (stack0_transport _ _ _ _ _ SK MU WM ltac:(eapply Forall_impl; [| exact FW]; intros ?iv ?HW; exact (proj1 (proj2 HW)))) as SKf;
    finish; [ exact FRlo
