(* [comment removed for export] *)

Lemma seg2_pwin : forall sp P IN E lo shi, stin_pure WRAP_STACK sp P IN E lo shi -> Forall pwin (seg2_W lo sp P E).
Proof.
  intros sp P IN E lo shi ((LO & CEIL & APP & PAL & APE & EAL & DPE & SPAL & SHI) & ILO & IHI & IAL).
  unfold seg2_W. repeat apply Forall_cons; [| | | | apply Forall_nil].
  - apply pwin_stack. exact CEIL.
  - eapply pwin_aapp; [exact APP| clear; lia| clear; lia].
  - eapply pwin_aapp; [exact APE| clear; lia| clear; lia].
  - exact pwin_httpcat.
Qed.

(* [comment removed for export] *)
Definition wrap_ctx (m0 m : mem) (sp s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav : word) (P IN E lo shi : Z) (c : pcore)
    (pad7 pad2 : list byte) (x y z : word) (in1 : Z) (Ef : ecv) : Prop :=
  rw_cells asegs m (bv_unsigned sp + -112) [C8 x; C8 y; C8 z]
  /\ rw_cells asegs m (bv_unsigned sp + -88) (wrap_saved s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav)
  /\ rw_cells asegs m P (ParserCoreCells c pad7 pad2)
  /\ rw_cells asegs m IN [C8 (wz in1)]
  /\ rw_cells asegs m E (ErrCodeCells Ef)
  /\ stk asegs m lo (bv_unsigned sp + -112)
  /\ munch (seg2_W lo sp P E) m0 m /\ wmono asegs m0 m /\ mem_inv asegs m
  /\ AHttpCat m true /\ st_side m0 P E lo shi.

(* [comment removed for export] *)
Definition seg2_done_stmt (pc_done : Z) : Prop :=
  forall rax rav sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s0v s1v s2v s2x s3v s3x s4v s4x s5v s6v s7v s8v s8x s9v s9x s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m0 m : mem) (P IN E lo shi : Z) (c : pcore) (pad7 pad2 : list byte) (x y z : word)
    (p0 in1 : Z) (Ef : ecv),
  wrap_ctx m0 m sp s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav P IN E lo shi c pad7 pad2 x y z in1 Ef ->
  pcore_ok c ->
  stin_pure WRAP_STACK sp P IN E lo shi ->
  p0 <= in1 <= p0 + pc_hlim c -> 0 <= p0 -> in1 < 2^64 ->
  evt asegs (seg2_post_e Ef rav sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10 s11 F fc P IN E lo shi c pad7 pad2 p0 in1 m0)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -112)) gp tp t0 t1 t2 (wz (P + 64)) (wz IN) a0 a1 a2 a3 a4 a5 a6 a7
              s2x s3x s4x (wz p0) (shw IN) (shw (P + 64)) s8x s9x s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc_done) fc None m (seg_rom asegs)).

Lemma le4_congr' (a b : word) : bv_unsigned a mod 2^32 = bv_unsigned b mod 2^32 -> le4 a = le4 b.
Proof. intros EQ. unfold le4. rewrite <- (Z_to_le_bytes_mod 4 (bv_unsigned a) 32), <- (Z_to_le_bytes_mod 4 (bv_unsigned b) 32) by (cbn; lia). rewrite EQ. reflexivity. Qed.

Local Ltac seg2_done_script :=
  unfold seg2_done_stmt;
  intros rax rav sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s0v s1v s2v s2x s3v s3x s4v s4x s5v s6v s7v s8v s8x s9v s9x s10 s11 t3 t4 t5 t6
         F fc m0 m P IN E lo shi c pad7 pad2 x y z p0 in1 Ef;
  intros CTX PCOK PURE IN1 P0 IN1H;
  destruct CTX as (TMP & FRhi & PC & IT & EC & ST & MU & WM & MI & HC & SIDE);
  pose proof (seg2_pwin _ _ _ _ _ _ PURE) as FW;
  destruct PURE as ((LO & CEIL & APP & PAL & APE & EAL & DPE & SPAL & SHI) & ILO & IHI & IAL);
  pose proof (stack0_bounds _ _ _ (pside2_stack0 _ _ _ _ _ SIDE)) as [SKB1 SKB2];
  pose proof (aapp_bounds _ 80 APP ltac:(lia)) as (PB1 & PB2 & PB3 & PB4 & PB5);
  pose proof (aapp_bounds _ 24 APE ltac:(lia)) as (EB1 & EB2 & EB3 & EB4 & EB5);
  pose proof aceil_facts as (AF1 & AF2 & AF3);
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  destruct PCOK as (Bh & Bl & Ln & Ln0 & Sk & Hl & Stt & Ff);
