(* [comment removed for export] *)
Lemma httpcat_id_read0 : forall m, ACONST m ->
  ov_read_bytes asegs m (Z_to_bv 64 (Z.shiftr (AG_HTTP_CAT + 8) 3 + 2147450880)) 1 = Some [b8 0].
Proof.
  intros m AC.
  apply (accessible_read0_sr m (AG_HTTP_CAT + 8) 8 (AG_HTTP_CAT + 8)); [| unfold AG_HTTP_CAT; lia | reflexivity | lia].
  apply (AsImgSh.ACONST_img_accessible m _ _ AC). vm_compute. reflexivity.
Qed.

(* [comment removed for export] *)
Lemma eqnm_b1 : forall lc, 0 <= lc < 2^64 -> lc <> 1 ->
  bv_eqb (v_sltiu (Z_to_bv 64 (lc + -1)) 1) (v_sltiu (Z_to_bv 64 2) 1) = true.
Proof.
  intros lc H H1. rewrite !v_sltiu_b2z, bv_eqb_Z. change (bv_wrap 64 1) with 1.
  rewrite (unsigned_lit 2) by lia.
  replace (bv_unsigned (Z_to_bv 64 (lc + -1)) <? 1) with false.
  2:{ symmetry. apply Z.ltb_ge. destruct (Z.eq_dec lc 0) as [->|].
      - rewrite unsigned_lit_wrap. change ((0 + -1) mod 2 ^ 64) with (2^64 - 1). lia.
      - rewrite unsigned_lit by lia. lia. }
  reflexivity.
Qed.
Lemma eqnm_nb1 : forall lc, 0 <= lc < 2^64 -> lc <> 1 ->
  negb (bv_eqb (v_sltiu (Z_to_bv 64 (lc + -1)) 1) (v_sltiu (Z_to_bv 64 2) 1)) = false.
Proof. intros lc H H1. rewrite (eqnm_b1 lc H H1). reflexivity. Qed.

